// cisOption allows management of the mutation configuration using functional options.
type cisOption func(*CisMutation)

// newCisMutation creates new mutation for the Cis entity.
func newCisMutation(c config, op Op, opts ...cisOption) *CisMutation {
	m := &CisMutation{
		config:        c,
		op:            op,
		typ:           TypeCis,
		clearedFields: make(map[string]struct{}),
	}
	for _, opt := range opts {
		opt(m)
	}
	return m
}

// withCisID sets the ID field of the mutation.
func withCisID(id uint64) cisOption {
	return func(m *CisMutation) {
		var (
			err   error
			once  sync.Once
			value *Cis
		)
		m.oldValue = func(ctx context.Context) (*Cis, error) {
			once.Do(func() {
				if m.done {
					err = errors.New("querying old values post mutation is not allowed")
				} else {
					value, err = m.Client().Cis.Get(ctx, id)
				}
			})
			return value, err
		}
		m.id = &id
	}
}

// withCis sets the old Cis of the mutation.
func withCis(node *Cis) cisOption {
	return func(m *CisMutation) {
		m.oldValue = func(context.Context) (*Cis, error) {
			return node, nil
		}
		m.id = &node.ID
	}
}

